+  context: "dispatch.test.ts",
+  agent: ${JSON.stringify(opts.agent ?? "reviewer")},
+  type: "pr",
+  number: ${opts.target},
+  repo: "owner/repo",
+  answersRequest: true,
+  ${opts.probeId !== undefined ? `freshnessProbeId: ${opts.probeId},` : ""}
+  ${opts.verdictPassed !== undefined ? `verdictPassed: ${opts.verdictPassed},` : ""}
